"""Publish validated end-to-end costs, investments and controls, including model limits."""
import json,html,hashlib,shutil
import calibrate_fighter as c
s=c.s;OUT=c.OUT

def main():
    chosen=json.loads((OUT/'fine-selection.json').read_text());best=chosen['trial']['result'];controls=json.loads((OUT/'fine-controls-results.json').read_text());detail=json.loads((OUT/'fine-detail-results.json').read_text())[0]['result'];resolution=json.loads((OUT/'fine-resolution-results.json').read_text());cat=json.loads((OUT/'fine.catalog.json').read_text())
    assert all(r['result']['success'] for r in controls+resolution)
    minimum=next(r['result'] for r in controls if r['id']=='minimum')
    assert json.loads((OUT/'fine-minimum-replay-results.json').read_text())[0]['result']==minimum
    for row in controls+resolution:
        assert row['result']['powerOffSeconds']==0
        assert next(x['amount'] for x in row['result']['produced']['stacks'] if x['item']=='fighter')==1
    data=dict(chosen=chosen,controls=controls,detail=detail,resolution=resolution,catalog=cat)
    counts=best['stages'][-1]['counts'];rows=''.join(f'<tr><td>{html.escape(k)}</td><td>{v}</td></tr>' for k,v in counts.items())
    starter=best['starter'];startlabel=f'{starter["iron"]} iron + {starter["copper"]} copper basic sets'
    status='Upgrade every starter set' if best['route']['replaceAll'] else 'Upgrade one iron and one copper set; keep remaining basic machines'
    files=list(OUT.glob('*-cases.json'));total=sum(len(json.loads(p.read_text())) for p in files)
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Factory progression to Fighter</title><style>:root{color-scheme:dark}body{font:16px system-ui;background:#10191d;color:#e5eeeb;max-width:1200px;margin:30px auto;padding:20px}p{color:#c0d0cb;line-height:1.6}a{color:#9ddacc}h1{font-size:38px}.cards{display:flex;gap:15px;flex-wrap:wrap}.cards>div{flex:1;min-width:180px;background:#24383c;border-radius:10px;padding:20px}.cards b{display:block;color:#9ddacc;font-size:30px}section{background:#1a292e;padding:20px;border:1px solid #38534e;border-radius:10px;margin:20px 0}table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums}td,th{padding:9px;text-align:left;border-bottom:1px solid #38534e;vertical-align:top}.scroll{overflow:auto;max-height:520px}select,button{font:inherit;background:#24383c;color:inherit;padding:8px;border:1px solid #668b80;border-radius:5px}.bar{height:15px;background:#86bca9;min-width:1px}code{font-size:14px}details{margin:12px 0}summary{cursor:pointer}</style>
<p><a href="starter-copper.html">← Starter copper experiment</a> · EXPERIMENTAL END-TO-END ECONOMY</p><h1>Invest through to one Fighter.</h1><p>Every route now ends with the same operational Fighter and commissioned Bay. Starter inventory, material production, machine purchases, research, fuel, electricity and every project phase carry forward through one simulation.</p>
<div class="cards"><div>Best tested route<b>BEST min</b></div><div>Minimum-capacity route<b>MINIMUM min</b></div><div>4× later capacity<b>EXCESS min</b></div></div>
<p>TRIALS simulation cases across economy sweeps, seeded route search, controls and validation. Final comparisons use 50 ms ticks; best/minimum are also checked at approximately 60 Hz below. Best tested does not mean globally optimal.</p>
<section><h2>What changed</h2><p>The starter copper profile is preserved. Relative to it: mechanical/fluid recipes run 8× faster; advanced structural/electrical recipes run 4× faster (plate, beam, wire and refractory recipes stay unchanged). Mechanical/fluid building and industrial-generator prices are 4× higher. Later research bills are RESEARCH× larger. Refunds remain 25%, and machines receive full power or are paused.</p><p><b>The starter optimum changes with the endpoint.</b> This best Fighter route starts with STARTLABEL, then follows: STARTMODE. The prior 4–2 result required upgrading every set and therefore does not establish the best route to a Fighter. Compare the 4–2 starter control below. Excess-capacity penalties are measured, not assumed to be 2×.</p><button id="download">Download experimental catalog</button><p>The live game catalog is unchanged. Saved profile: <code>Tools/Balance/reports/fighter-progression/fine.catalog.json</code>.</p></section>
<section><h2>Underinvestment and overinvestment</h2><div class="scroll"><table><thead><tr><th>Controlled route</th><th>Finish min</th><th>Difference from best</th><th>Relative duration</th></tr></thead><tbody id="controls"></tbody></table></div><p>Capacity multipliers apply to industrial target counts at each stage, keeping the starter route fixed. “Target 1” changes only that family’s industrial target; surviving basic machines and already-built industrial machines remain. These are capacity comparisons, not pure single-machine causal measurements.</p></section>
<section><h2>Progress and factory counts</h2><label>Route <select id="route"></select></label><div class="scroll"><table><thead><tr><th>Milestone</th><th>Reached min</th><th>Stage min</th><th>Installed factory</th></tr></thead><tbody id="stages"></tbody></table></div><p>Stage durations include resource production, funding waits, construction and research/project timers. Purchases occur in a fixed family order; this search varies quantities, stage timing, starter allocation and whether to retain basic machines.</p></section>
<section><h2>Best route: purchase order</h2><p>Funded purchases and stage transitions from the same simulation. A purchase timestamp is when materials were paid; it is not necessarily construction completion.</p><div class="scroll"><table><thead><tr><th>Minute</th><th>Action</th><th>Details</th></tr></thead><tbody id="events"></tbody></table></div></section>
<section><h2>Completed factory and resources</h2><details><summary>Installed machines at Fighter completion</summary><table><thead><tr><th>Machine/resource</th><th>Count</th></tr></thead><tbody>COUNTS</tbody></table></details><p id="resources"></p><p>Mining totals include surplus stock and fuel production; they are not just the Fighter's material bill.</p></section>
<section><h2>Validation and limits</h2><div id="resolution"></div><p>The selected coarse route and minimum route replayed exactly in serial and parallel execution; the detailed 50 ms ledger matches the final fine-step result. The simulation produces one operational Fighter with no fractional-power operation. Half-second results were unsuitable for fast recipes and are retained only as a search archive.</p><p>Transfers remain ideal manual logistics with no belt throughput or player-placement-time limit. Existing belt power is charged. Silica/refractory building and research charges remain omitted from the earlier experiment; recipes and Bay phases still consume those materials and silicate mining is included. Coal and generator purchases are automatically sized to installed load plus research/project reserve; power planning is not independently optimized. Research and project phase rules come from the game simulation. This is a numerical balance candidate, not a validated physical belt layout or a finished whole-game balance.</p></section>
<script>const data=DATA;const best=data.chosen.trial.result;function cell(tr,v){const td=document.createElement('td');td.textContent=v;tr.appendChild(td);return td}const controlBody=document.querySelector('#controls');for(const r of data.controls){const tr=document.createElement('tr');cell(tr,r.id);cell(tr,(r.result.seconds/60).toFixed(2));cell(tr,((r.result.seconds-best.seconds)/60).toFixed(2));const td=cell(tr,'');const b=document.createElement('div');b.className='bar';b.style.width=Math.min(100,r.result.seconds/Math.max(...data.controls.map(x=>x.result.seconds))*100)+'%';td.appendChild(b);controlBody.appendChild(tr)}const routes=[{id:'Best tested',result:best},...data.controls];const select=document.querySelector('#route');routes.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.id;select.appendChild(o)});function show(){document.querySelector('#stages').replaceChildren(...routes[select.value].result.stages.map(m=>{const tr=document.createElement('tr');cell(tr,m.label);cell(tr,(m.seconds/60).toFixed(2));cell(tr,(m.duration/60).toFixed(2));cell(tr,Object.entries(m.counts).filter(([k])=>k!=='core'&&k!=='belt').map(([k,v])=>v+' '+k).join(', '));return tr}))}select.onchange=show;show();document.querySelector('#events').replaceChildren(...data.detail.events.map(e=>{const tr=document.createElement('tr');cell(tr,(e.time/60).toFixed(2));cell(tr,e.kind);cell(tr,e.detail);return tr}));const mined=best.produced.stacks.filter(x=>['iron','copperOre','carbon','silicate'].includes(x.item));document.querySelector('#resources').textContent='Mined: '+mined.map(x=>x.amount.toLocaleString()+' '+x.item).join('; ')+'. Energy: '+best.energyPUHours.toFixed(1)+' game power-unit hours.';document.querySelector('#resolution').textContent='50 ms: best '+(best.seconds/60).toFixed(2)+' min; minimum '+(data.controls.find(r=>r.id==='minimum').result.seconds/60).toFixed(2)+' min. Approx. 60 Hz: '+data.resolution.map(r=>r.id+' '+(r.result.seconds/60).toFixed(2)+' min').join('; ')+'.';document.querySelector('#download').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data.catalog,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='fighter-balance.catalog.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};</script></html>'''
    excess=next(r['result'] for r in controls if r['id']=='capacity-4x')
    vals={'BEST':f'{best["seconds"]/60:.1f}','MINIMUM':f'{minimum["seconds"]/60:.1f}','EXCESS':f'{excess["seconds"]/60:.1f}','TRIALS':str(total),'RESEARCH':str(chosen['research']),'STARTLABEL':startlabel,'STARTMODE':status,'COUNTS':rows,'DATA':json.dumps(data).replace('</','<\\/')}
    for k,v in vals.items():page=page.replace(k,v)
    (OUT/'report.html').write_text(page,encoding='utf-8');(s.HERE/'web/fighter-progression.html').write_text(page,encoding='utf-8')
    sources=list(s.HERE.glob('*.cs'))+list(s.HERE.glob('*.ps1'))+list(s.HERE.glob('*fighter*.py'))+[s.HERE/'calibrate_starter.py']+list((s.ROOT/'Assets/Scripts').glob('Factory*.cs'));manifest={}
    for f in sources:
        rel=f.relative_to(s.ROOT);dest=OUT/'source'/rel;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(f,dest);manifest[str(rel)]=hashlib.sha256(f.read_bytes()).hexdigest()
    s.write(OUT/'source-sha256.json',manifest)
    print('Published fighter-progression.html; cases',total,'best',best['seconds']/60,'minimum',minimum['seconds']/60)

if __name__=='__main__':main()
